import re
from decimal import Decimal

# Limits are expressed in integer cents so that no decimal context is involved.
MAX_CENTS = 100_000_000  # 1000000.00

# Plain decimal: optional sign, digits, optional fraction. No whitespace,
# underscores, exponents, or non-finite spellings.
_PLAIN_DECIMAL = re.compile(r"[+-]?[0-9]+(?:\.[0-9]+)?")


def _to_decimal(value):
    if isinstance(value, bool):
        raise ValueError("booleans are not valid amounts")
    if isinstance(value, Decimal):
        return value
    if isinstance(value, int):
        # Decimal(int) is exact and does not consult the context.
        return Decimal(value)
    if isinstance(value, str):
        if not _PLAIN_DECIMAL.fullmatch(value):
            raise ValueError(f"invalid amount string: {value!r}")
        # Decimal(str) is exact and does not consult the context.
        return Decimal(value)
    raise ValueError(f"unsupported amount type: {type(value).__name__}")


def amount_to_cents(value):
    """Validate an amount and return it as an exact integer number of cents."""
    d = _to_decimal(value)
    if not d.is_finite():
        raise ValueError("amount must be finite")
    if d.is_zero():
        raise ValueError("amount must be nonzero")
    if d.is_signed():
        raise ValueError("amount must be positive")
    # Nonzero and finite, so adjusted() is the exponent of the leading digit.
    # Anything >= 10**7 is over the limit; checking this first keeps the
    # arithmetic below bounded for huge exponents.
    if d.adjusted() > 6:
        raise ValueError("amount exceeds 1000000.00")

    _sign, digits, exp = d.as_tuple()
    coeff = int("".join(map(str, digits)))
    if exp >= -2:
        cents = coeff * 10 ** (exp + 2)
    else:
        shift = -2 - exp  # digits beyond the cent position
        if shift >= len(digits):
            # coeff is nonzero and smaller than 10**shift, so it cannot be a
            # multiple of 10**shift: there is a nonzero fractional cent.
            raise ValueError("amount is not exactly representable in cents")
        divisor = 10 ** shift
        if coeff % divisor:
            raise ValueError("amount is not exactly representable in cents")
        cents = coeff // divisor

    if cents > MAX_CENTS:
        raise ValueError("amount exceeds 1000000.00")
    return cents


def cents_to_decimal(cents):
    """Return a non-negative integer number of cents as a Decimal with exponent -2."""
    return Decimal(f"{cents // 100}.{cents % 100:02d}")


def parse_amount(value):
    return cents_to_decimal(amount_to_cents(value))


def format_amount(value):
    return format(value, ".2f")

