import re
from decimal import Context, Decimal, ROUND_DOWN

# Private context used only for exactness checks. It is never installed
# globally, so the caller's decimal context is neither read nor changed.
_CTX = Context(prec=60, rounding=ROUND_DOWN)
_CENT = Decimal("0.01")
_MAX_DECIMAL = Decimal("1000000.00")
MAX_CENTS = 100_000_000  # 1000000.00
_PLAIN_DECIMAL = re.compile(r"[+-]?(?:[0-9]+(?:\.[0-9]+)?|\.[0-9]+)")


def parse_cents(value):
    """Validate an amount and return it as an integer number of cents."""
    if isinstance(value, bool):
        raise ValueError("boolean is not an amount")
    if isinstance(value, Decimal):
        d = Decimal(value)
    elif isinstance(value, int):
        d = Decimal(int(value))
    elif isinstance(value, str):
        if not _PLAIN_DECIMAL.fullmatch(value):
            raise ValueError(f"not a plain decimal string: {value!r}")
        d = Decimal(value)
    else:
        raise ValueError(f"unsupported amount type: {type(value).__name__}")

    if not d.is_finite():
        raise ValueError("amount must be finite")
    if d <= 0:
        raise ValueError("amount must be positive")
    if d > _MAX_DECIMAL:
        raise ValueError("amount must be at most 1000000.00")
    # Truncating to cents must not discard a nonzero fraction of a cent.
    q = d.quantize(_CENT, rounding=ROUND_DOWN, context=_CTX)
    if q != d:
        raise ValueError("amount is not exactly representable in cents")
    return int(q.scaleb(2, context=_CTX))


def cents_to_decimal(cents):
    """Return an exact Decimal with exponent -2 for a non-negative cent count."""
    return Decimal(f"{cents // 100}.{cents % 100:02d}")


def parse_amount(value):
    return cents_to_decimal(parse_cents(value))


def format_amount(value):
    return format(value, ".2f")

