import re
from decimal import Decimal

MAX_CENTS = 100_000_000  # 1000000.00

# Plain decimal strings: optional sign, no whitespace, no exponent.
_PLAIN_DECIMAL = re.compile(r"[+-]?(?:[0-9]+(?:\.[0-9]*)?|\.[0-9]+)")


def _decimal_to_cents(value):
    """Return the signed integer cent count of a finite Decimal.

    Uses only exact tuple/integer arithmetic, so the active decimal context
    is never consulted or modified. Raises ValueError for values that are
    not finite or that have a nonzero fractional cent.
    """
    if not value.is_finite():
        raise ValueError("non-finite amount")
    sign, digits, exp = value.as_tuple()
    if not any(digits):
        return 0
    # Value lies in [10**(L+exp-1), 10**(L+exp)); if L+exp >= 8 it is >= 10**7.
    if len(digits) + exp > 7:
        raise ValueError("amount exceeds 1000000.00")
    ds = list(digits)
    # Drop trailing zeros that lie beyond the cent position.
    while exp < -2 and ds[-1] == 0:
        ds.pop()
        exp += 1
    if exp < -2:
        raise ValueError("amount is not exactly representable in cents")
    cents = int("".join(map(str, ds))) * 10 ** (exp + 2)
    return -cents if sign else cents


def parse_cents(value):
    """Validate an amount and return it as a positive integer cent count."""
    if isinstance(value, bool):
        raise ValueError("boolean is not an amount")
    if isinstance(value, Decimal):
        cents = _decimal_to_cents(value)
    elif isinstance(value, int):
        cents = value * 100
    elif isinstance(value, str):
        if _PLAIN_DECIMAL.fullmatch(value) is None:
            raise ValueError(f"invalid amount string: {value!r}")
        cents = _decimal_to_cents(Decimal(value))
    else:
        raise ValueError(f"unsupported amount type: {type(value).__name__}")
    if cents <= 0:
        raise ValueError("amount must be positive")
    if cents > MAX_CENTS:
        raise ValueError("amount exceeds 1000000.00")
    return cents


def cents_to_amount(cents):
    """Return an exact Decimal with exponent -2 for an integer cent count."""
    whole, frac = divmod(cents, 100)
    return Decimal(f"{whole}.{frac:02d}")


def parse_amount(value):
    return cents_to_amount(parse_cents(value))

def format_amount(value):
    return format(value, ".2f")

