import re
from decimal import Decimal

MAX_CENTS = 100_000_000  # 1000000.00

# Plain decimal string: optional sign, digits with optional fraction.
# No whitespace, no exponent, ASCII digits only.
_PLAIN_DECIMAL = re.compile(r"[+-]?(?:[0-9]+(?:\.[0-9]*)?|\.[0-9]+)")


def _to_decimal(value):
    if isinstance(value, bool):
        raise ValueError("booleans are not amounts")
    if isinstance(value, Decimal):
        return value
    if isinstance(value, int):
        return Decimal(value)
    if isinstance(value, str):
        if not _PLAIN_DECIMAL.fullmatch(value):
            raise ValueError(f"not a plain decimal string: {value!r}")
        return Decimal(value)
    raise ValueError(f"unsupported amount type: {type(value).__name__}")


def parse_cents(value):
    """Validate an amount and return it as a positive int number of cents.

    Uses only integer/string operations so the global decimal context
    is never consulted or modified.
    """
    d = _to_decimal(value)
    if not d.is_finite():
        raise ValueError("amount must be finite")
    sign, digits, exp = d.as_tuple()
    raw = "".join(map(str, digits))
    stripped = raw.rstrip("0")
    if not stripped:
        raise ValueError("amount must be nonzero")
    if sign:
        raise ValueError("amount must be positive")
    # Exponent of the last nonzero digit.
    e = exp + (len(raw) - len(stripped))
    if e < -2:
        raise ValueError("amount is not exactly representable in cents")
    # cents = int(stripped) * 10**(e + 2); check digit count before building
    # the integer so huge exponents cannot cause large allocations.
    if len(stripped) + e + 2 > len(str(MAX_CENTS)):
        raise ValueError("amount exceeds 1000000.00")
    cents = int(stripped + "0" * (e + 2))
    if cents > MAX_CENTS:
        raise ValueError("amount exceeds 1000000.00")
    return cents


def cents_to_amount(cents):
    """Return a Decimal with exponent -2 for a non-negative int of cents."""
    return Decimal((0, tuple(int(c) for c in str(cents)), -2))


def parse_amount(value):
    return cents_to_amount(parse_cents(value))


def format_amount(value):
    return format(value, ".2f")

