def test_insert_and_update_counts():
    c = fresh()
    add_contact(c, "a@b.com", "Old")
    res = import_contacts(c, [
        {"email": "  New@X.com ", "name": " Neo "},
        {"email": "a@b.com", "name": "Old"},
    ])
    assert res == {"inserted": 1, "updated": 1}, res
    assert list_contacts(c) == [("a@b.com", "Old"), ("new@x.com", "Neo")]

