    "x",
    {"email": "a@b.com"},
    {"email": "a@b.com", "name": "A", "extra": 1},
    {"email": "a@@b.com", "name": "A"},
    {"email": "ab.com", "name": "A"},
    {"email": "@b.com", "name": "A"},
    {"email": "a@", "name": "A"},
    {"email": "a b@c.com", "name": "A"},
    {"email": "a@b.com", "name": "   "},
    {"email": 1, "name": "A"},
]

