    for row in BAD_ROWS:
        c = fresh()
        add_contact(c, "keep@x.com", "Keep")
        assert raises(ValueError, lambda: import_contacts(c, [{"email": "ok@x.com", "name": "Ok"}, row])), row
        assert list_contacts(c) == [("keep@x.com", "Keep")], row

