    """Validate an amount and return it as integer cents (1..MAX_CENTS)."""
    if isinstance(value, bool):
        raise ValueError("bool is not a valid amount")
    if isinstance(value, int):
        return _check_cents(value * 100)
    if isinstance(value, Decimal):
        return _check_cents(_cents_from_decimal(value))
    if isinstance(value, str):
        if not _PLAIN_DECIMAL.fullmatch(value):
            raise ValueError("amount must be a plain decimal string")
        return _check_cents(_cents_from_decimal(Decimal(value)))
    raise ValueError(f"unsupported amount type: {type(value).__name__}")


