from decimal import Decimal

MAX_AMOUNT_CENTS = 100_000_000  # 1000000.00

# Plain decimal: optional sign, digits with an optional fraction. No whitespace,
# no exponent, no underscores. [0-9] is used instead of \d so that non-ASCII
# digits are rejected.
_PLAIN_DECIMAL = re.compile(r"[+-]?(?:[0-9]+\.?[0-9]*|\.[0-9]+)")
_MAX_DECIMAL = Decimal("1000000.00")


def amount_to_cents(value):
    """Validate an amount and return it as an exact integer number of cents.

    Uses only exact integer and Decimal operations (no rounding, and no reliance
    on the decimal context), so the global context is never read or changed.
    """
    if isinstance(value, bool):
        raise ValueError("boolean is not a valid amount")
    if isinstance(value, int):
        number = Decimal(value)
    elif isinstance(value, Decimal):
        number = value
    elif isinstance(value, str):
        if _PLAIN_DECIMAL.fullmatch(value) is None:
            raise ValueError(f"not a plain decimal string: {value!r}")
        number = Decimal(value)
    else:
        raise ValueError(f"unsupported amount type: {type(value).__name__}")

    if not number.is_finite():
        raise ValueError("amount must be finite")
    if number <= 0:
        raise ValueError("amount must be greater than zero")
    if number > _MAX_DECIMAL:
        raise ValueError("amount must not exceed 1000000.00")

    _sign, digits, exponent = number.as_tuple()
    coefficient = int("".join(map(str, digits)))
    # Strip trailing zeros only while the value still has more than two
    # fractional digits; any nonzero digit beyond the cent place is an error.
    while exponent < -2 and coefficient % 10 == 0:
        coefficient //= 10
        exponent += 1
    if exponent < -2:
        raise ValueError("amount is not exactly representable in cents")
    return coefficient * 10 ** (exponent + 2)


def cents_to_amount(cents):
    """Return an integer number of cents as a Decimal with exponent -2."""
    return Decimal(f"{cents // 100}.{cents % 100:02d}")


def parse_amount(value):
    return cents_to_amount(amount_to_cents(value))


def format_amount(value):
    return format(value, ".2f")

