import re
from decimal import Context, Decimal, ROUND_DOWN, ROUND_HALF_EVEN, InvalidOperation, Overflow, DivisionByZero

_CENT = Decimal("0.01")
_MAX_AMOUNT = Decimal("1000000.00")
_STRING_RE = re.compile(r"[+-]?[0-9]+(?:\.[0-9]+)?")


def _context():
    # A private context: never reads or mutates the caller's global decimal context.
    return Context(
        prec=40,
        rounding=ROUND_HALF_EVEN,
        Emin=-999999,
        Emax=999999,
        capitals=1,
        clamp=0,
        flags=[],
        traps=[InvalidOperation, Overflow, DivisionByZero],
    )


def parse_amount(value):
    """Parse a money amount into a Decimal with exponent -2.

    Accepts Decimal, int (not bool), and plain decimal strings (optionally
    signed, no whitespace, no exponent). Raises ValueError for anything else,
    for non-finite, zero or negative values, values above 1000000.00, and
    values that are not exactly representable in cents.
    """
    if isinstance(value, bool):
        raise ValueError("amount must not be a bool")
    if isinstance(value, Decimal):
        d = Decimal(value)
    elif isinstance(value, int):
        d = Decimal(int(value))
    elif isinstance(value, str):
        if not _STRING_RE.fullmatch(value):
            raise ValueError(f"invalid amount string: {value!r}")
        d = Decimal(value)
    else:
        raise ValueError(f"unsupported amount type: {type(value).__name__}")

    if not d.is_finite():
        raise ValueError("amount must be finite")
    if d <= 0:
        raise ValueError("amount must be positive")
    if d > _MAX_AMOUNT:
        raise ValueError("amount must be at most 1000000.00")

    ctx = _context()
    cents = d.quantize(_CENT, rounding=ROUND_DOWN, context=ctx)
    if cents != d:
        raise ValueError("amount is not exactly representable in cents")
    return cents


def format_amount(value):
    return format(value, ".2f")

