from .repository import contact_exists, put_contact

_ROW_FIELDS = frozenset(("email", "name"))

def add_contact(connection, email, name):
    with connection:
        put_contact(connection, email, name)

def _normalize_row(index, row):
    if not isinstance(row, dict):
        raise ValueError(f"row {index} must be an object")
    keys = set(row)
    missing = _ROW_FIELDS - keys
    if missing:
        raise ValueError(f"row {index} is missing fields: {sorted(missing)}")
    unknown = keys - _ROW_FIELDS
    if unknown:
        raise ValueError(f"row {index} has unknown fields: {sorted(map(repr, unknown))}")
    email, name = row["email"], row["name"]
    if not isinstance(email, str) or not isinstance(name, str):
        raise ValueError(f"row {index} email and name must be strings")
    email = email.strip()
    name = name.strip()
    if not name:
        raise ValueError(f"row {index} name must not be empty")
    if not email or any(ch.isspace() for ch in email):
        raise ValueError(f"row {index} email must be non-empty and contain no whitespace")
    if email.count("@") != 1:
        raise ValueError(f"row {index} email must contain exactly one '@'")
    local, domain = email.split("@")
    if not local or not domain:
        raise ValueError(f"row {index} email must have text on both sides of '@'")
    return email.lower(), name

def import_contacts(connection, rows):
    if not isinstance(rows, (list, tuple)):
        raise ValueError("rows must be a list")

    # Validate the complete batch before touching the database.
    batch = []
    seen = set()
    for index, row in enumerate(rows):
        email, name = _normalize_row(index, row)
        if email in seen:
            raise ValueError(f"row {index} duplicates email {email!r} within the batch")
        seen.add(email)
        batch.append((email, name))

    if not batch:
        return {"inserted": 0, "updated": 0}

    inserted = updated = 0
    try:
        # Connections are idle at entry, so this opens the transaction.
        connection.execute("BEGIN IMMEDIATE")
        for email, name in batch:
            if contact_exists(connection, email):
                updated += 1
            else:
                inserted += 1
            put_contact(connection, email, name)
        connection.commit()
    except BaseException:
        if connection.in_transaction:
            connection.rollback()
        raise
    return {"inserted": inserted, "updated": updated}

