from .repository import find_existing_emails, put_contact

_FIELDS = frozenset(("email", "name"))

def add_contact(connection, email, name):
    with connection:
        put_contact(connection, email, name)

def _normalize_row(index, row):
    if not isinstance(row, dict):
        raise ValueError("row %d must be an object" % index)
    keys = set(row)
    missing = _FIELDS - keys
    if missing:
        raise ValueError("row %d is missing fields: %s" % (index, ", ".join(sorted(missing))))
    unknown = keys - _FIELDS
    if unknown:
        raise ValueError("row %d has unknown fields: %s" % (index, ", ".join(sorted(str(k) for k in unknown))))
    email, name = row["email"], row["name"]
    if not isinstance(email, str) or not isinstance(name, str):
        raise ValueError("row %d email and name must be strings" % index)
    email = email.strip()
    name = name.strip()
    if email.count("@") != 1:
        raise ValueError("row %d email must contain exactly one '@'" % index)
    local, domain = email.split("@")
    if not local or not domain:
        raise ValueError("row %d email must have nonempty local and domain parts" % index)
    if any(ch.isspace() for ch in email):
        raise ValueError("row %d email must not contain whitespace" % index)
    if not name:
        raise ValueError("row %d name must not be empty" % index)
    return email.lower(), name

def import_contacts(connection, rows):
    if not isinstance(rows, (list, tuple)):
        raise ValueError("rows must be a list")
    records = {}
    for index, row in enumerate(rows):
        email, name = _normalize_row(index, row)
        if email in records:
            raise ValueError("row %d duplicates email %r within the batch" % (index, email))
        records[email] = name
    if not records:
        return {"inserted": 0, "updated": 0}
    connection.execute("BEGIN IMMEDIATE")
    try:
        existing = find_existing_emails(connection, records)
        for email, name in records.items():
            put_contact(connection, email, name)
        connection.commit()
    except BaseException:
        connection.rollback()
        raise
    updated = sum(1 for email in records if email in existing)
    return {"inserted": len(records) - updated, "updated": updated}
